/* Vidéo & motion : plans, mouvements de caméra, transitions de montage, habillage, rythme & son, image & formats.
   Les démos reposent sur un cadre 16:9 (.vf) en trois couches : fond (ciel), milieu (collines), avant (personnages). */
const PA = `<span class="ppl"><i></i><i></i></span>`, PB = `<span class="ppl b"><i></i><i></i></span>`;
function SCN(o = {}) {
  const day = `<div class="lay bg sky" style="${o.bg || ""}"><span class="sun"></span></div><div class="lay mid" style="${o.mid || ""}"><span class="h1"></span><span class="h2"></span><span class="tree"></span></div>`;
  const night = `<div class="lay bg night" style="${o.bg || ""}"><span class="moon" style="${o.moon || ""}"></span></div><div class="lay mid" style="${o.mid || ""}"><span class="city"></span></div>`;
  return `<div class="vf">${o.tag ? `<span class="tag">${o.tag}</span>` : ""}<div class="lay w" style="${o.w || ""}">${o.night ? night : day}<div class="lay fg" style="${o.fg || ""}">${o.two ? PB : ""}${o.solo === false ? "" : o.pl ? PA.replace('class="ppl"', `class="ppl" style="${o.pl}"`) : PA}</div>${o.flower ? `<span class="flower" style="${o.fl || ""}"></span>` : ""}</div>${o.grid ? `<span class="grid3"></span>` : ""}${o.extra || ""}</div>`;
}
const DAYL = `<div class="lay bg sky"><span class="sun"></span></div><div class="lay mid"><span class="h1"></span><span class="h2"></span><span class="tree"></span></div><div class="lay fg">${PA}</div>`;
const NIGHTL = (moon = "") => `<div class="lay bg night"><span class="moon" style="${moon}"></span></div><div class="lay mid"><span class="city"></span></div>`;
const TWO = (extra = "", moon = "", sb = "") => `<div class="vf"><div class="lay sa">${DAYL}</div><div class="lay sb" style="opacity:0;${sb}">${NIGHTL(moon)}</div><span class="flash"></span><span class="blk"></span>${extra}</div>`;
/* Joue fn en boucle tant que la démo est affichée */
const cycle = (st, fn, period) => { let k = 0; const run = () => { if (!st.isConnected) return; fn(k++); setTimeout(run, period); }; setTimeout(run, 400); return () => fn(k++); };
/* Plan : la démo part du plan large et cadre le plan visé */
const shot = (o, tf, origin) => ({ h: SCN({ ...o, w: `transform:${tf};transform-origin:${origin}` }), init: st => { const w = $(st, ".w"); return () => w.animate([{ transform: "none" }, { transform: "none", offset: .25 }, { transform: tf }], { duration: 1600, easing: "cubic-bezier(.65,0,.35,1)" }); } });
const A = (el, kf, o) => el.animate(kf, typeof o === "number" ? { duration: o, easing: "cubic-bezier(.65,0,.35,1)", fill: "forwards" } : { fill: "forwards", ...o });
const loopCam = (bg, mid, fg, dur = 4, extra = {}) => ({ h: SCN({ ...extra, bg: bg && `animation:${bg} ${dur}s ease-in-out infinite alternate;transform-origin:62% 60%`, mid: mid && `animation:${mid} ${dur}s ease-in-out infinite alternate;transform-origin:62% 60%`, fg: fg && `animation:${fg} ${dur}s ease-in-out infinite alternate;transform-origin:62% 60%` }), noloop: 1 });

